def _half_ellipse(cx, cy, rx, ry, n=16):
    """Upper half of an ellipse, as a polygon."""
    return [(cx + rx * math.cos(math.pi + math.pi * k / n), cy + ry * math.sin(math.pi + math.pi * k / n)) for k in range(n + 1)]


