def _transform(rig, name, point, pose):
    while name is not None:
        group = rig[name]
        dx, dy, degrees = pose.get(name, (0, 0, 0))
        px, py = pose.get(name + "_pivot", group["pivot"])
        a = math.radians(degrees)
        sx, sy = pose.get(name + "_scale", (1, 1))
        x, y = (point[0] - px) * sx, (point[1] - py) * sy
        point = (px + x * math.cos(a) - y * math.sin(a) + dx, py + x * math.sin(a) + y * math.cos(a) + dy)
        name = group["parent"]
    return point


def _shift(colour, amount):
    """Lighter (amount > 0) or darker, nudging hue warm in light, cool in shadow."""
    r, g, b = (int(colour[i:i + 2], 16) for i in (0, 2, 4))
    if amount > 0:
        r, g, b = r + (255 - r) * amount, g + (255 - g) * amount * 0.92, b + (255 - b) * amount * 0.8
    else:
        k = 1 + amount
        r, g, b = r * k * 0.94, g * k * 0.97, b * k * 1.05
    return "%02x%02x%02x" % tuple(max(0, min(255, int(v))) for v in (r, g, b))


def _rich_tone(shades, t, x, y):
    """Five tones from a material's three, dithered where bands meet."""
    tones = [_shift(shades[0], 0.18), shades[0], shades[1], shades[2], _shift(shades[2], -0.25)]
    edges = [0.16, 0.34, 0.62, 0.84]
    band = sum(1 for e in edges if t >= e)
    for index, edge in enumerate(edges):
        if abs(t - edge) < 0.035 and (x + y) % 2 == 0:
            band = index if t >= edge else index + 1
    return tones[band]


# Surface texture by material, so fur, stone, bone, ghostly light and
# flesh read differently at a glance. Patterns use part-relative
# coordinates (u, v) so they travel with the part from frame to frame.
TEXTURES = {
    "fur": ["hide", "frost_fur", "bristle", "troll", "feather", "wool", "bear", "wolf_fur", "wolf_dark", "cow_patch"],
    "stone": ["stone", "obsidian", "plate_dark"],
    "bone": ["bone", "rib", "tooth", "wrap_pale"],
    "spectral": ["ghost", "storm", "void_skin"],
    "flesh": ["flesh", "imp", "lurker", "wound", "skin"],
    "chitin": ["chitin", "sand_chitin"],
    "wood": ["bark", "wood"],
    "slime": ["slime", "lava", "poison"],
}
TEXTURE_OF = {material: kind for kind, materials in TEXTURES.items() for material in materials}


def _hash2(u, v):
    return ((u * 73856093) ^ (v * 19349663) ^ 0x5bd1e995) & 0xffff


def _textured(material, colour, u, v):
    kind = TEXTURE_OF.get(material)
    if kind == "fur":
        # Short strands running down and back, with lit tips.
        k = (u * 2 + v) % 6
        if k == 0:
            return _shift(colour, -0.2)
        if k == 3 and v % 2 == 0:
            return _shift(colour, 0.1)
    elif kind == "stone":
        # Blocky grain and the odd crack.
        h = _hash2(u // 2, v // 2) % 9
        if (u + 2 * v) % 13 == 0 and h < 4:
            return _shift(colour, -0.32)
        if h == 0:
            return _shift(colour, -0.14)
        if h == 1:
            return _shift(colour, 0.12)
    elif kind == "bone":
        # Faint growth lines and pores.
        if _hash2(u, v) % 23 == 0:
            return _shift(colour, -0.28)
        if v % 5 == 0:
            return _shift(colour, -0.07)
    elif kind == "spectral":
        # Streaming wisps of lighter light and thin dark gaps.
        if (u + v // 2) % 5 == 0:
            return _shift(colour, 0.2)
        if v % 4 == 3 and u % 2 == 0:
            return _shift(colour, -0.12)
    elif kind == "flesh":
        # Mottling and a thread of vein.
        if abs((u * 0.6 + math.sin(v * 0.55) * 2.0) % 9 - 4.5) < 0.45:
            return _shift(colour, -0.2)
        if _hash2(u // 3, v // 3) % 5 == 0:
            return _shift(colour, -0.1)
    elif kind == "chitin":
        # Overlapping plates: a dark seam with a lit lip below it.
        if v % 5 == 0:
            return _shift(colour, -0.26)
        if v % 5 == 1:
            return _shift(colour, 0.12)
    elif kind == "wood":
        if (u * 3 + v // 4) % 7 == 0:
            return _shift(colour, -0.16)
    elif kind == "slime":
        if _hash2(u, v) % 17 == 0:
            return _shift(colour, 0.35)
    return colour


def _palette_finish(pixels, materials):
    """For palette-swapped art (the player's body, worn layers): light the
    top-left edge of each shape and shade its underside using only the
    material's own three tones, so recolouring still works."""
    out = dict(pixels)
    for (x, y), colour in pixels.items():
        material = materials.get((x, y))
        shades = PALETTE.get(material)
        if not shades or shades[0] == shades[2]:
            continue
        up, left, down = (x, y - 1) in pixels, (x - 1, y) in pixels, (x, y + 1) in pixels
        if not up or not left:
            out[(x, y)] = shades[0]
        elif not down:
            out[(x, y)] = shades[2]
    return out


def _finish(pixels, plain):
    """Rim light on top-left edges, occlusion along the bottom, and an
    outline tinted by the colour it wraps instead of flat black."""
    out = dict(pixels)
    for (x, y), colour in pixels.items():
        if (x, y) in plain:
            continue
        up, left, down, right = (x, y - 1) in pixels, (x - 1, y) in pixels, (x, y + 1) in pixels, (x + 1, y) in pixels
        if not up or not left:
            out[(x, y)] = _shift(colour, 0.22)
        elif not down:
            out[(x, y)] = _shift(colour, -0.3)
        elif not right:
            out[(x, y)] = _shift(colour, -0.15)
    return out


def draw_frame(rig, order, pose, shadow=True, rich=False, outline=True):
    ox, oy = FRAME_OFFSET
    pixels = {}
    materials = {}
    plain = set()
    for name in order:
        for material, polygon in rig[name]["parts"]:
            moved = [_transform(rig, name, pt, pose) for pt in polygon]
            mask = Image.new("L", (FRAME, FRAME), 0)
            ImageDraw.Draw(mask).polygon([(x + ox, y + oy) for x, y in moved], fill=255, outline=255)
            points = [(x, y) for y in range(FRAME) for x in range(FRAME) if mask.getpixel((x, y))]
            if not points:
                continue
            x0, x1 = min(p[0] for p in points), max(p[0] for p in points)
            y0, y1 = min(p[1] for p in points), max(p[1] for p in points)
            shades = PALETTE[material]
            flat = shades[0] == shades[2]
            for x, y in points:
                t = 0.7 * (x - x0) / max(x1 - x0, 1) + 0.3 * (y - y0) / max(y1 - y0, 1)
                materials[(x, y)] = material
                if rich and not flat:
                    pixels[(x, y)] = _textured(material, _rich_tone(shades, t, x, y), x - x0, y - y0)
                    plain.discard((x, y))
                else:
                    # Skin keeps its light tone over more of the shape, so
                    # faces read as their true colour, not their shadow.
                    light, mid = (0.45, 0.88) if material == "skin" else (0.3, 0.68)
                    pixels[(x, y)] = shades[0 if t < light else 1 if t < mid else 2]
                    if flat:
                        plain.add((x, y))

    img = Image.new("RGBA", (FRAME, FRAME), (0, 0, 0, 0))
    shadow_x, shadow_w = pose.get("shadow", (22, 9))[:2]
    if shadow:
        ImageDraw.Draw(img).ellipse((shadow_x + ox - shadow_w, GROUND_Y - 2, shadow_x + ox + shadow_w, GROUND_Y + 2), fill=(0, 0, 0, 90))
    if rich:
        pixels = _finish(pixels, plain)
    elif outline:
        pixels = _palette_finish(pixels, materials)
    for (x, y), colour in pixels.items():
        img.putpixel((x, y), rgba(colour))
    for y in range(FRAME if outline else 0):
        for x in range(FRAME):
            if (x, y) in pixels:
                continue
            near = [pixels[(x + dx, y + dy)] for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)) if (x + dx, y + dy) in pixels]
            if near:
                if rich:
                    r, g, b = (int(near[0][i:i + 2], 16) for i in (0, 2, 4))
                    o = (int(OUTLINE[0:2], 16), int(OUTLINE[2:4], 16), int(OUTLINE[4:6], 16))
                    img.putpixel((x, y), (int(o[0] * 0.7 + r * 0.22), int(o[1] * 0.7 + g * 0.22), int(o[2] * 0.7 + b * 0.22), 255))
                else:
                    img.putpixel((x, y), rgba(OUTLINE))
    return img


def blend(a, b, t):
    """Pose between two poses, t from 0 to 1."""
    out = {}
    for key in set(a) | set(b):
        default = (0, 0, 0)
        if key.endswith("_pivot") or key == "shadow":
            default = a.get(key, b.get(key))
        elif key.endswith("_scale"):
            default = (1, 1)
        va, vb = a.get(key, default), b.get(key, default)
        out[key] = tuple(x + (y - x) * t for x, y in zip(va, vb))
    return out


def keyframes(keys):
    """Poses from [(frame, pose), ...], blending between neighbours."""
    poses = []
    for i in range(keys[-1][0] + 1):
        for (f0, p0), (f1, p1) in zip(keys, keys[1:]):
            if f0 <= i <= f1:
                poses.append(blend(p0, p1, (i - f0) / max(f1 - f0, 1)))
                break
    return poses


def cycle(n, pose_at):
    """A looping animation: pose_at(sine of the phase) for each of n frames."""
    return [pose_at(math.sin(2 * math.pi * i / n)) for i in range(n)]


# --- human animations (frame counts follow the animation spec in the game)
